// same list, prefixed, for gen_extern_h.sh dependency tracking
const nvi_inputs = blk: {
    var out: [nvi_sources.len][]const u8 = undefined;
    for (nvi_sources, 0..) |s, i| out[i] = "src.freebsd/nvi/" ++ s;
    break :blk out;
};
